#!/usr/bin/env python3
# luxarch:edit-history hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""Before a session first changes a file, it searches LuxPM for that file: a hold on it lives there.

A red burn-down works one rule across many files, so the agent reaches each file knowing only the
red on it. It does not know the line is on hold. Typical holds: a fix waiting on an upstream
release, a site another agent is working on, an escalation that says not to port a sibling's
workaround. Agents went straight past such holds, and "fixed" reds by moving the code where the
rule no longer looked. Rule: FLEET-AGENT-CONDUCT-STANDARD, "Before you change code to clear a red".

Why LuxPM and not git. Measured on three fleet repos, 91-99% of tracked files have commits that
name issue keys, so a key list per file is noise. The held file that prompted this rule (an
`on_hold` escalation on a conftest) was never committed under its hold's key. Its 15 commits named
12 OTHER keys. A LuxPM search for the file's path found the hold as its first `on_hold` hit.

PreToolUse(Edit | Write | MultiEdit | NotebookEdit | Bash). The first change this session makes to
a tracked file is denied until the session has searched LuxPM for that file: a
`luxpm_list_issues(search=...)` or `luxpm_semantic_search(query=...)` whose term contains the file's
name. `luxpm-search-mark` records each term when the search returns. The denial names the search
to run, and shows the file's last 3 commits as context. A new file and anything outside the
checkout pass. So does every change when the session has no id, or its terms cannot be
remembered: a gate that waits for a record it can never see would lock the file forever.

What it cannot check: that the agent read the results. An `on_hold` issue, another agent's
`in_progress` issue, or an open escalation covering the code is a hold, and the standard says
what to do with it. It reads text only, and every git call is bounded in time.
"""

from __future__ import annotations

import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import edited
from _ledger import read_event, search_terms, session_id, terms_writable, tree_dir

_TOOLS = ("Edit", "Write", "MultiEdit", "NotebookEdit", "Bash")
_GIT_ERRORS = (OSError, subprocess.SubprocessError)
# bound to a name: an inline `except (A, B)` formats differently under py314 (PEP 758)
_PATH_ERRORS = (ValueError, OSError)


def _git(root: Path, *args: str) -> str | None:
    try:
        r = subprocess.run(
            ["git", "-C", str(root), *args],
            capture_output=True,
            text=True,
            timeout=4,
            check=False,
        )
    except _GIT_ERRORS:
        return None
    return r.stdout if r.returncode == 0 else None


def searched_for(rel: str, terms: list[str]) -> bool:
    """A recorded search term names this file: its name, or a path ending in it."""
    name = Path(rel).name.lower()
    return any(name in t.lower() for t in terms)


def main() -> int:
    ev = read_event()
    if str(ev.get("tool_name") or "") not in _TOOLS:
        return 0
    path, _old, _new = edited(ev)
    ti = ev.get("tool_input")
    if not path and isinstance(ti, dict):
        path = str(ti.get("notebook_path") or "")
    if not path or not session_id():
        return 0
    root = tree_dir()
    p = Path(path)
    p = p if p.is_absolute() else root / p
    try:
        rel = p.resolve().relative_to(root.resolve()).as_posix()
    except _PATH_ERRORS:
        return 0  # outside the checkout: not this repo's code
    if searched_for(rel, search_terms()) or not terms_writable():
        return 0
    if _git(root, "ls-files", "--error-unmatch", "--", f":(literal){rel}") is None:
        return 0  # untracked or new: nothing can be held on it yet
    recent = (
        _git(root, "log", "-n3", "--format=  %h %cs %s", "--", f":(literal){rel}") or ""
    ).rstrip()
    print(
        f"HISTORY CHECK: search LuxPM for {rel} before your first change to it this session.\n"
        f'  luxpm_list_issues(search="{rel}")  (this repo\'s project; read every hit, not the titles)\n'
        "A hit that is on_hold, in_progress under another agent, or an open escalation covering this "
        "code means the site is HELD: do not change it. Name it in one line (key, file, why) and go on "
        "to the next red. A red moved to another file or out of a rule's sight is not a fix.\n"
        "Once the search has run, retry this edit: it passes.\n"
        + (f"Recent commits on it:\n{recent}\n" if recent else "")
        + 'See --doc FLEET-AGENT-CONDUCT-STANDARD, "Before you change code to clear a red".',
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(0)
